const controllers=require('./controllers');
const assert = require('node:assert/strict'), fs = require('node:fs'), vm = require('node:vm'), path = require('node:path');
const c = vm.createContext({});
controllers.run(fs.readFileSync(path.join(process.argv[2], 'visual-state.js'), 'utf8'), c);
const state = c.MonitorObservations, base = Date.parse('2026-11-07T01:00:00Z');
function snap(n, extra={}) { return {instance_id:'one',generated_at:new Date(base+n).toISOString(),stages:{a:{site:'a',stage:'detail',queue:{queue_len:0,in_progress:4,completed:12,failed:0}}},...extra}; }
assert.equal(state.accept({}), false);
assert.equal(state.accept(snap(0)), true); assert.equal(state.accept(snap(0)), false);
assert.equal(state.trend(null,'queued')[0].y, 0); assert.equal(state.trend(null,'unfinished')[0].y,4);
state.trend('a','queued'); assert.equal(state.size(),1, 'site projection is not a sample');
state.accept(snap(3000,{stages:{}})); assert.equal(state.trend(null,'queued')[1].y,null,'stage change breaks line');
assert.equal(state.trend(null,'queued').at(-1).y,null,'no stage is not a measured zero');
state.accept(snap(30000)); assert.equal(state.trend(null,'queued').at(-2).y,null,'long disconnection');
state.accept(snap(100)); assert.equal(state.size(),1,'clock rollback resets');
state.accept(snap(200,{instance_id:'two'})); assert.equal(state.size(),1,'restart resets');
for(let n=1;n<500;n++) state.accept(snap(n*1000,{instance_id:'two'}));
assert.equal(state.size(),240); state.accept(snap(1200000,{instance_id:'two'})); assert.equal(state.size(),1,'window expires');
state.reset(); assert.equal(state.size(),0);
const system={cpu_available:true,cpu_percent:0,cpu_sampled_at:new Date(base).toISOString(),sample_interval_ms:30000};
assert.equal(state.resource({},'cpu',base).state,'尚无成功采样');
assert.equal(state.resource(system,'cpu',base+80000).value,0,'configured long sampler interval respected');
assert.equal(state.resource(system,'cpu',base+100000).state,'样本过期');
assert.equal(state.resource({...system,cpu_available:false},'cpu',base).state,'采样失败');
state.accept(snap(0,{system})); state.accept(snap(3000,{system})); assert.equal(state.resourceTrend('cpu').length,1,'HTTP poll is not a new system sample');
state.accept(snap(6000,{system:{...system,cpu_available:false}})); assert.equal(state.resourceTrend('cpu').at(-1).y,null);
assert.equal(state.resource({...system,cpu_sampled_at:new Date(base+1).toISOString()},'cpu',base).value,null,'future timestamp unavailable');
console.log('visual observations: identity, bounds, discontinuities, scope and validity passed');
state.reset();
for(let n=0;n<=60000;n+=3000) state.accept(snap(n,{system:{...system,cpu_percent:25,cpu_sampled_at:new Date(base+Math.floor(n/30000)*30000).toISOString()}}));
assert.equal(state.resourceTrend('cpu').length,3,'continuous polls and slow sampler do not imply disconnect');
assert.ok(state.resourceTrend('cpu').every(p=>p.y===25));
state.reset();state.accept(snap(0));state.accept(snap(1,{stages:{}}));
const fast=state.trend(null,'queued');assert.ok(fast.every((p,i)=>i===0||p.x>fast[i-1].x),'sub-poll interval gap must have strictly increasing x');
state.reset();
for(const n of [0,3000,21000,24000,27000,30000]) state.accept(snap(n,{system:{...system,cpu_sampled_at:new Date(base+(n===30000?30000:0)).toISOString()}}));
assert.equal(state.resourceTrend('cpu').length,3);assert.equal(state.resourceTrend('cpu')[1].y,null,'reconnection with duplicate resource stamp must retain break');
state.accept({});assert.equal(state.size(),0,'metadata-less response cannot retain a trusted old trend next to fresh bars');
state.accept(snap(0,{stages:{a:{site:'a',queue:{queue_len:0,in_progress:-1,completed:1,failed:0}}}}));
assert.equal(state.trend(null,'unfinished')[0].y,null,'non-atomic worker counter undershoot must remain unknown, not zero');
